package owl.nh;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
public final class KioskPrivacyTests {
 static void check(boolean yes,String message){CoreTests.check(yes,"Kiosk privacy: "+message);}
 public static void main(String[] args)throws Exception{java.util.List<String> names=Arrays.asList("Turbo");check(KioskText.spans("Turbo: hello TURBO",names).size()==2,"match all case-insensitive name instances");check(KioskText.spans("Turbocharged turbo_123",names).isEmpty(),"do not mask unrelated longer names");check(KioskText.title("Orion - Turbo",names).equals("Orion - \u2588\u2588\u2588\u2588\u2588"),"native title keeps the app name and masks the account");check(KioskText.spans("a+b",Arrays.asList("a+b")).size()==1,"names are literal, never interpreted as regular expressions");Rectangle box=new Rectangle(20,40,200,16);java.util.List<Rectangle> masks=KioskText.masks("<col=ff0000>Turbo</col>: hello",box,0,0,14,t->KioskText.plain(t).length()*6,names);check(masks.size()==1&&masks.get(0).x==20&&masks.get(0).width<=34,"strip covers name without blanking the rest of chat");check(KioskText.masks("nothing private",box,0,0,14,t->t.length()*6,names).isEmpty(),"unrelated text remains visible");
  Map<String,Object> wf=new HashMap<>();wf.put("getText","Turbo: hello");wf.put("getBounds",box);wf.put("isVisible",true);wf.put("getLineHeight",14);net.runelite.api.widgets.Widget w=ChambersTests.fake(net.runelite.api.widgets.Widget.class,wf);Map<String,Object> pf=new HashMap<>();pf.put("getName","Turbo");pf.put("getLogicalHeight",100);pf.put("getCanvasTextLocation",new net.runelite.api.Point(120,120));net.runelite.api.Player player=ChambersTests.fake(net.runelite.api.Player.class,pf);Map<String,Object> cf=new HashMap<>();cf.put("getLocalPlayer",player);cf.put("getUsername","Turbo");cf.put("getWidgetRoots",new net.runelite.api.widgets.Widget[]{w});net.runelite.api.Client client=ChambersTests.fake(net.runelite.api.Client.class,cf);KioskPrivacy privacy=new KioskPrivacy(client);BufferedImage image=new BufferedImage(320,200,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setColor(Color.WHITE);g.fillRect(0,0,320,200);privacy.overlay.render(g);g.dispose();check(image.getRGB(23,45)==Color.BLACK.getRGB(),"chat name is covered by an opaque strip even without a running bot");check(image.getRGB(290,170)==Color.WHITE.getRGB(),"unrelated game pixels remain untouched");check(w.getText().equals("Turbo: hello")&&player.getName().equals("Turbo"),"game identity and widget text remain unchanged");java.util.List<Rectangle> dps=KioskDpsMask.rows(new Rectangle(10,20,180,54),new Rectangle(4,4,4,4),2,Arrays.asList("Other","Turbo"),false,names,t->t.length()*6);check(dps.size()==1&&dps.get(0).x<=14&&dps.get(0).y>40,"DPS row masking follows panel placement and only selects the local name");check(dps.get(0).width<50&&dps.get(0).x+dps.get(0).width<160,"damage value and unrelated columns remain visible");check(KioskDpsMask.rows(new Rectangle(200,100,180,54),new Rectangle(4,4,4,4),2,Arrays.asList("Other","Turbo"),false,names,t->t.length()*6).get(0).x==dps.get(0).x+190,"dragging the DPS overlay moves its name mask");check(KioskDpsMask.rows(new Rectangle(0,0,180,54),new Rectangle(4,4,4,4),2,Arrays.asList("Other","Someone"),false,names,t->t.length()*6).isEmpty(),"other players in DPS panel are not censored");Object plugin=Class.forName("net.runelite.client.plugins.dpscounter.DpsCounterPlugin").getDeclaredConstructor().newInstance();Class<?> memberClass=Class.forName("net.runelite.client.plugins.dpscounter.DpsMember");java.lang.reflect.Constructor<?> memberCtor=memberClass.getDeclaredConstructor(String.class);memberCtor.setAccessible(true);Object member=memberCtor.newInstance("Turbo");java.lang.reflect.Field damage=memberClass.getDeclaredField("damage");damage.setAccessible(true);damage.setInt(member,10);java.lang.reflect.Field membersField=plugin.getClass().getDeclaredField("members");membersField.setAccessible(true);((Map)membersField.get(plugin)).put("Turbo",member);java.lang.reflect.Constructor<?> overlayCtor=Class.forName("net.runelite.client.plugins.dpscounter.DpsOverlay").getDeclaredConstructors()[0];overlayCtor.setAccessible(true);net.runelite.client.ui.overlay.Overlay nativeDps=(net.runelite.client.ui.overlay.Overlay)overlayCtor.newInstance(plugin,null,null,client,null);nativeDps.setBounds(new Rectangle(10,20,180,40));check(KioskDpsMask.rectangles(nativeDps,names,t->t.length()*6).size()==1,"read-only adapter resolves the actual installed native DPS overlay and local member row");check(KioskDpsMask.renderedText("<col=ff00ff00>Turbo").equals("<col=ff00ff00>Turbo"),"malformed eight-digit DPS tags are measured as literal visible characters");check(KioskDpsMask.renderedText("<col=ffff00>Turbo</col>").equals("Turbo"),"supported DPS colour markup has no visible width");java.util.List<Rectangle> tagged=KioskDpsMask.rows(new Rectangle(0,0,400,40),new Rectangle(4,4,4,4),2,Arrays.asList("<col=ff00ff00>Turbo"),false,names,t->t.length()*6);check(tagged.size()==1&&tagged.get(0).x>70,"DPS strip follows the visible name after a literal tag prefix");
Map<String,Object> parentFields=new HashMap<>();parentFields.put("getBounds",new Rectangle(20,100,200,40));parentFields.put("isVisible",true);net.runelite.api.widgets.Widget chatParent=ChambersTests.fake(net.runelite.api.widgets.Widget.class,parentFields);Map<String,Object> scrolledFields=new HashMap<>();scrolledFields.put("getParent",chatParent);scrolledFields.put("getBounds",new Rectangle(20,80,200,16));scrolledFields.put("isVisible",true);net.runelite.api.widgets.Widget scrolled=ChambersTests.fake(net.runelite.api.widgets.Widget.class,scrolledFields);check(KioskPrivacy.visibleBounds(scrolled)==null,"a name scrolled above the chat viewport produces no strip");scrolledFields.put("getBounds",new Rectangle(20,94,200,16));Rectangle partiallyVisible=KioskPrivacy.visibleBounds(scrolled);check(partiallyVisible.y==100&&partiallyVisible.height==10,"partly visible chat row is clipped at viewport edge");scrolledFields.put("getBounds",new Rectangle(20,110,200,16));check(KioskPrivacy.visibleBounds(scrolled).height==16,"visible name remains masked normally");scrolledFields.put("getBounds",new Rectangle(20,150,200,16));check(KioskPrivacy.visibleBounds(scrolled)==null,"row below the viewport is not painted either");System.out.println("Kiosk privacy checks passed: title, literal names, chat strips, passive idle rendering and untouched game state. Synthetic only.");}
}



